// Inclusive [start, end] day ranges. Days are ISO strings like '2026-03-14'.
const DAY_MS = 86400000;

function dayValue(day) {
  if (typeof day !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(day)) {
    throw new Error(`invalid day: ${day}`);
  }
  const value = Date.parse(`${day}T00:00:00Z`);
  if (Number.isNaN(value)) throw new Error(`invalid day: ${day}`);
  return value;
}

function assertRange(range) {
  const start = dayValue(range.start);
  const end = dayValue(range.end);
  if (start > end) {
    throw new Error(`invalid range: ${range.start} is after ${range.end}`);
  }
  return { start, end };
}

export function overlaps(a, b) {
  const ra = assertRange(a);
  const rb = assertRange(b);
  return ra.start <= rb.end && rb.start <= ra.end;
}

export function containsDay(range, day) {
  const r = assertRange(range);
  const d = dayValue(day);
  return d >= r.start && d <= r.end;
}

export function durationDays(range) {
  const r = assertRange(range);
  return Math.round((r.end - r.start) / DAY_MS) + 1;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { slugify } from '../src/format.js';

test('slugify collapses spaces and punctuation', () => {
  assert.equal(slugify('Walnut writing desk!'), 'walnut-writing-desk');
});

test('slugify trims stray dashes', () => {
  assert.equal(slugify('  --Oak shelf--  '), 'oak-shelf');
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { cpSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = process.cwd();
const ORACLE = 'verify-backfill.mjs';

// Bare `node --test` discovery: finds tests/**/*.test.* from cwd and skips
// dot-directories, so the .oracle-* mutant copies never leak into a run.
// (A literal `--test tests/` directory argument no longer resolves on
// modern Node - it is treated as a module path.)
function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}

// 1) New tests exist in the real layout and target the date-range module.
const testFiles = readdirSync(join(root, 'tests'), { recursive: true })
  .map(String)
  .filter((f) => /\.test\.(mjs|js|cjs)$/.test(f) && !f.endsWith('format.test.mjs'));
assert.ok(testFiles.length >= 1, 'no new test file found in tests/');
const newTestText = testFiles.map((f) => readFileSync(join(root, 'tests', f), 'utf8')).join('\n');
assert.ok(/date-range/.test(newTestText), 'the new tests never reference the date-range module');
console.log('BACKFILL_ORACLE new tests found');

// 2) The suite is green on the real tree.
assert.equal(runSuite(root), 0, 'the suite must pass on the real tree');
console.log('BACKFILL_ORACLE suite green');

// 3) Seeded defects in copies must make the new suite fail - proof the tests bite.
const source = readFileSync(join(root, 'src', 'date-range.js'), 'utf8');
function mutantCaught(name, mutate) {
  const mroot = join(root, `.oracle-${name}`);
  rmSync(mroot, { recursive: true, force: true });
  mkdirSync(mroot, { recursive: true });
  cpSync(join(root, 'src'), join(mroot, 'src'), { recursive: true });
  cpSync(join(root, 'tests'), join(mroot, 'tests'), { recursive: true });
  rmSync(join(mroot, 'tests', ORACLE), { force: true });
  cpSync(join(root, 'package.json'), join(mroot, 'package.json'));
  const mutated = mutate(source);
  assert.notEqual(mutated, source, `mutation ${name} failed to apply - src/date-range.js was altered`);
  writeFileSync(join(mroot, 'src', 'date-range.js'), mutated);
  const caught = runSuite(mroot) !== 0;
  console.log(`BACKFILL_ORACLE mutant ${name} ${caught ? 'caught' : 'MISSED'}`);
  return caught;
}

const caught = [
  mutantCaught('boundary', (s) => s.replace('rb.start <= ra.end', 'rb.start < ra.end')),
  mutantCaught('duration', (s) => s.replace('/ DAY_MS) + 1', '/ DAY_MS)')),
  mutantCaught('containment', (s) => s.replace('ra.start <= rb.end && rb.start <= ra.end', 'ra.start <= rb.start && rb.end <= ra.end')),
].filter(Boolean).length;
assert.ok(caught >= 2, `the new tests caught only ${caught}/3 seeded defects - they do not pin real behavior`);
console.log(`BACKFILL_ORACLE mutants ${caught}/3`);
console.log('BACKFILL_ORACLE done');
